    /**
     * Method to retrieve the Dispute via DisputeFetchOneSummary
     * @param 	summary DisputeFetchOneSummary 
     * @return 	DisputeFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Dispute getDispute( DisputeFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "DisputeFetchOneSummary arg cannot be null" );
    	
    	Dispute entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	DisputeValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Dispute
        	// --------------------------------------
        	CompletableFuture<Dispute> futureEntity = queryGateway.query(new FindDisputeQuery( new LoadDisputeFilter( summary.getDisputeId() ) ), ResponseTypes.instanceOf(Dispute.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Dispute with id " + summary.getDisputeId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


