    /**
     * assign Transaction on Dispute
     * @param		command AssignTransactionToDisputeCommand	
     * @exception	ProcessingException
     */     
	public void assignTransaction( AssignTransactionToDisputeCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getDisputeId() );
		
		TransactionService childDelegate 	= TransactionService.getTransactionInstance();
		DisputeService parentDelegate = DisputeService.getDisputeInstance();			
		UUID childId = command.getAssignment().getTransactionId();
		Transaction child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	DisputeValidator.getInstance().validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Transaction using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

